// -- ESS GridSetpoint für OldGrid berechnen
// - wenn Old Grid Überschuss hat, diesen absaugen
// - wenn der SOC unter minSOC fällt, auf std. -200W
// - Old Grid stützen
schedule("*/5 * * * * *", async () => {
  if (getState('0_userdata.0.Victron.OldGrid_zu_NewGrid').val && (getState('alias.0.EM24 Old Grid.Power Old Grid').val < -500) && (getState('alias.0.Gobel.SOC').val < getState('0_userdata.0.Victron.Old_Grid_Setpoint_minSOC').val) && ((getState('alias.0.EM24 Hall Grid.Power').val > -1000) || getState('javascript.0.Victron.ChargerV3').val || getState('javascript.0.Victron.ChargerV4').val)) {
    setState('mqtt.1.ioBroker.ESS_GridSetpoint' /* ioBroker/ESS_GridSetpoint */, (Math.min(Math.max(getState('alias.0.EM24 Old Grid.Power Old Grid').val * -1, 0), 5000)));
  } else if (getState('0_userdata.0.Victron.Old_Grid_Setpoint').val && (getState('alias.0.Gobel.SOC').val > getState('0_userdata.0.Victron.Old_Grid_Setpoint_minSOC').val) && (getState('alias.0.EM24 Old Grid.Power Old Grid Plus').val > 100)) {
    setState('mqtt.1.ioBroker.ESS_GridSetpoint' /* ioBroker/ESS_GridSetpoint */, (Math.min(Math.max(10 * (Math.round(getState('alias.0.EM24 Old Grid.Power Old Grid').val * 10) / 10 / 10), 200), 10000) * -1));
  } else if (false) {
  } else {
    setState('mqtt.1.ioBroker.ESS_GridSetpoint' /* ioBroker/ESS_GridSetpoint */, getState('0_userdata.0.Victron.New_Grid_Setpoint').val);
  }
});
// -- deaktiviert
on({ id: '0_userdata.0.Victron.Old_Grid_Setpoint' /* Old_Grid_Setpoint */, val: false }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  setState('mqtt.1.ioBroker.ESS_GridSetpoint' /* ioBroker/ESS_GridSetpoint */, getState('0_userdata.0.Victron.New_Grid_Setpoint').val);
});


